commit 814807594587218259d899a0ab2ad39a1fa82c26
Author: Kenneth Jiang <kenneth.jiang@gmail.com>
Date:   Wed Oct 21 16:24:18 2026 -0700

    Let a host application set OrcaSlicer's accent colour

    OrcaSlicer's accent, the teal behind ColorRGB::ORCA() and
    ColorRGBA::ORCA(), is now read from ColorRGB::orca_accent(), which
    defaults to the same teal and can be set. Two load-time copies of it now
    read it at use instead, with their call sites unchanged:
    ImGuiWrapper::COL_ORCA (a macro over the new col_orca()) and IMSlider's
    BRAND_COLOR. ImGui's style table, filled once when ImGuiWrapper is
    constructed, can be filled again through ImGuiWrapper::reset_style().

    apply_brand_palette sets the accent to the action colour from the tokens
    and refills the style table, after start-up and on each appearance change.
    That recolours the ImGui and GL layer's accent: the preview sliders'
    handles, filled track and value text, gizmo highlights, the selection
    rectangle. The sliders' greys, value boxes and handle shape stay
    OrcaSlicer's.
	static const ColorRGB DARK_YELLOW() { return { 0.5f, 0.5f, 0.0f }; }
	static const ColorRGB GRAY()        { return { 0.5f, 0.5f, 0.5f }; }
	static const ColorRGB GREEN()       { return { 0.0f, 1.0f, 0.0f }; }
	static const ColorRGB GREENISH()    { return { 0.5f, 1.0f, 0.5f }; }
	static const ColorRGB LIGHT_GRAY()  { return { 0.75f, 0.75f, 0.75f }; }
	static const ColorRGB MAGENTA()     { return { 1.0f, 0.0f, 1.0f }; }
	static const ColorRGB ORANGE()      { return { 0.92f, 0.50f, 0.26f }; }
	static const ColorRGB RED()         { return { 1.0f, 0.0f, 0.0f }; }
	static const ColorRGB REDISH()      { return { 1.0f, 0.5f, 0.5f }; }
	static const ColorRGB YELLOW()      { return { 1.0f, 1.0f, 0.0f }; }
	static const ColorRGB WHITE()       { return { 1.0f, 1.0f, 1.0f }; }
    static const ColorRGB ORCA()		{ return orca_accent(); }
    // The accent ORCA() returns: OrcaSlicer's teal unless a host application sets its own before drawing.
    static ColorRGB& orca_accent()      { static ColorRGB accent{0.0f, 150.f / 255.0f, 136.0f / 255}; return accent; }
	static const ColorRGB WARNING()     { return {241.0f / 255, 117.f / 255.0f, 78.0f / 255}; }

	static const ColorRGB X()           { return { 255 / 255.f, 60  / 255.f, 91  / 255.f};}
	static const ColorRGB Y()           { return { 100 / 255.f, 200 / 255.f, 24  / 255.f};}
	static const ColorRGB Z()           { return { 47  / 255.f, 136 / 255.f, 233 / 255.f};}
};

