    if (!overlay_tick || current_fps > 0 || m_render_stats.get_scene_fps() > 0)
        m_fps_overlay_timer.StartOnce(1000);
}

if (wxGetApp().plater()->is_render_statistic_dialog_visible()) {
    ImGui::ShowMetricsWindow();

