        dlg.select_tab(tab, highlight_option);
        dlg.ShowModal();
        need_recreate_gui = dlg.recreate_GUI();
        pending_language = dlg.pending_language();
        if (!need_recreate_gui) {
            this->plater_->get_current_canvas3D()->force_set_focus();
#if ENABLE_GCODE_LINES_ID_IN_H_SLIDER
            if (dlg.seq_top_layer_only_changed() || dlg.seq_seq_top_gcode_indices_changed())
#else
            if (dlg.seq_top_layer_only_changed())
#endif // ENABLE_GCODE_LINES_ID_IN_H_SLIDER
                this->plater_->reload_print();
#ifdef _WIN32
            if (is_editor()) {
                if (app_config->get("associate_3mf") == "true")
                    associate_files(L"3mf");
                if (app_config->get("associate_stl") == "true")
                    associate_files(L"stl");
                if (app_config->get("associate_step") == "true") {
                    associate_files(L"step");
                    associate_files(L"stp");
                }
#ifndef SLIC3R_NO_ORCASLICER_URL_ASSOCIATION
                associate_url(L"orcaslicer");
#endif
            }
            else {
                if (app_config->get("associate_gcode") == "true")
                    associate_files(L"gcode");
            }
#endif // _WIN32
        }
    }
        // The Preferences window is gone, so say why nothing happened.
        wxMessageBox(_L("JusPrin couldn't close the project, so it didn't restart. Your project stays open, and JusPrin "
                        "will use the new language the next time it starts."),
                     _L("Restart"), wxOK | wxICON_INFORMATION, app.mainframe);
    }
}

