    const std::string hover   = hex(p.action_primary_hover);
    const std::string text    = hex(p.text_primary);
    return {
        {"\"#009688\"", "\"" + primary + "\""},
        {"\"#0x00AE42\"", "\"" + primary + "\""},
        {"\"#00FF00\"", "\"" + hover + "\""},
        {"#009688", primary},
        {"#00675b", primary},
        {"#26A69A", hover},
        {"#52c7b8", hover},
        // Monochrome brand mark and icon line work follow the text color.
        {"\"#262E30\"", "\"" + text + "\""},
        {"#262E30", text},
    };
}

} // namespace

void apply_brand_palette()
{
    // Brand artwork under OrcaSlicer's asset names; see resources/jusprin/overlay/README.md.
    set_var_overlay_dir((boost::filesystem::path(resources_dir()) / "jusprin" / "overlay" / "images").string());

    const ShellTheme* theme = brand_theme();
    if (theme == nullptr)
        return;

    const ShellPalette& p = theme->palette(GUI_App::dark_mode());
    StateColor::SetColorOverrides(widget_overrides(p));
    BitmapCache::SetColorReplaces(icon_replaces(p));
    // OrcaSlicer's own accent in the ImGui and GL layer: the preview sliders'
    // handles, filled track and value text, gizmo highlights, the selection
    // rectangle. Its readers evaluate it at use; ImGui's style table is the
    // one copy made at start-up, before this runs, so it is filled again.
    ColorRGB::orca_accent() = ColorRGB(p.action_primary.Red() / 255.f, p.action_primary.Green() / 255.f,
                                       p.action_primary.Blue() / 255.f);
    // Its other shades: OrcaSlicer draws the dark ones on a dark canvas, and
    // p is already this appearance's palette, so both pairs take the same
    // tokens. They colour the plate toolbar and the gizmos' checkboxes.
    const auto im_colour = [](const wxColour& c) { return ImVec4(c.Red() / 255.f, c.Green() / 255.f, c.Blue() / 255.f, 1.f); };
    ImGuiWrapper::col_orca_dark()       = im_colour(p.action_primary);
    ImGuiWrapper::col_orca_hover()      = im_colour(p.action_primary_hover);
    ImGuiWrapper::col_orca_hover_dark() = im_colour(p.action_primary_hover);
    if (ImGuiWrapper* imgui = wxGetApp().imgui())
        imgui->reset_style();
}

} // namespace Slic3r::GUI::JusPrin

