    });
}

void ShellController::leave_print_history()
{
    m_frame->CallAfter([this] {
        if (!m_installed || m_history_return_tab < 0)
            return;
        m_tabpanel->SetSelection(std::exchange(m_history_return_tab, -1));
    });
}

