const lines = fs.readFileSync(process.argv[2], 'utf8').split(/\r?\n/).filter(Boolean);
const byFile = new Map();
for (const line of lines) {
    const m = line.match(/upstream-2\.5\.0[\\/](.*?)\((\d+)/);
    const file = m ? m[1] : line.slice(0, 100);
    if (!byFile.has(file)) byFile.set(file, []);
    byFile.get(file).push(line);
}
for (const [file, v] of [...byFile].sort((a, b) => b[1].length - a[1].length)) {
    const kinds = [...new Set(v.map(x => (x.match(/error (C\d+|LNK\d+)/) || [])[1]))];
    console.log(String(v.length).padStart(4), file, kinds.join(','));
}

