// Lists each translatable literal in the fork's confirmation table and whether
// OrcaSlicer's GUI sources still contain it, joining adjacent C string pieces.
import fs from 'node:fs';
const [table, ...sources] = process.argv.slice(2);
const join = (text) => text.replace(/"\s*\n\s*"/g, '');
const literals = (text, re) => [...join(text).matchAll(re)].map((m) => m[1]);
const ours = literals(fs.readFileSync(table, 'utf8'), /_u?8?L\("((?:[^"\\]|\\.)*)"\)/g);
const theirs = sources.map((f) => join(fs.readFileSync(f, 'utf8'))).join('\n');
for (const s of ours) {
    const found = theirs.includes(`"${s}"`) || theirs.includes(s);
    console.log(found ? 'ok     ' : 'MISSING', s.slice(0, 110));
}

