// Resolves minidbg frames like "module!export+0x1234" against an MSVC /MAP
// file: the export's address plus the offset, then the nearest public symbol
// at or below it. Usage: node mapstack.mjs <map> <minidbg output> <module>
import fs from 'node:fs';
import readline from 'node:readline';

const [mapPath, stackPath, module] = process.argv.slice(2);
const symbols = [];
const byName = new Map();
const lines = readline.createInterface({ input: fs.createReadStream(mapPath) });
// "  0001:00000000       ?name@@...       0000000140001000 f   obj.obj"
const re = /^\s+[0-9a-f]{4}:[0-9a-f]{8}\s+(\S+)\s+([0-9a-f]{16})\s/i;
for await (const line of lines) {
    const m = re.exec(line);
    if (!m) continue;
    const address = BigInt('0x' + m[2]);
    if (address === 0n) continue;
    symbols.push([address, m[1]]);
    if (!byName.has(m[1])) byName.set(m[1], address);
}
symbols.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));

const nearest = (address) => {
    let lo = 0, hi = symbols.length - 1, best = -1;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (symbols[mid][0] <= address) { best = mid; lo = mid + 1; } else hi = mid - 1;
    }
    return best < 0 ? null : symbols[best];
};

const frame = new RegExp(`^(#\\d+) ${module}!(.+?)\\+0x([0-9A-F]+)$`, 'i');
const seen = new Set();
for (const line of fs.readFileSync(stackPath, 'utf8').split(/\r?\n/)) {
    if (line.startsWith('===')) { if (seen.has('second')) break; if (line.includes('second-chance')) seen.add('second'); console.log(line); continue; }
    const m = frame.exec(line);
    if (!m) { if (line.startsWith('#')) console.log(line); continue; }
    // minidbg names the export; the map spells exports undecorated, as here.
    const base = byName.get(m[2]) ?? byName.get(m[2].replace(/^.*::/, ''));
    if (base === undefined) { console.log(`${m[1]} ?? ${m[2]}+0x${m[3]}`); continue; }
    const hit = nearest(base + BigInt('0x' + m[3]));
    console.log(`${m[1]} ${hit ? hit[1] : '??'}`);
}

