int Plater::new_project(bool skip_confirm, bool silent, const wxString& project_name, bool reload_presets)
{
    bool transfer_preset_changes = false;
    // BBS: save confirm
    auto check = [this,&transfer_preset_changes](bool yes_or_no) {
        m_new_project_and_check_state = true;
        wxString header = _L("Some presets are modified.") + "\n" +
            (yes_or_no ? _L("You can keep the modified presets for the new project or discard them") :
                _L("You can keep the modified presets for the new project, discard, or save changes as new presets."));
        int act_buttons = ActionButtons::KEEP | ActionButtons::REMEMBER_CHOISE;
        if (!yes_or_no)
            act_buttons |= ActionButtons::SAVE;
        if (m_exported_file) { //.gcode.3mf ignore presets modify
            m_exported_file = false;
        }
        bool result = wxGetApp().check_and_keep_current_preset_changes(_L("Creating a new project"), header, act_buttons, &transfer_preset_changes);
        m_new_project_and_check_state = false;
        return result;
    };
    int result;
    if ((!skip_confirm && (result = close_with_confirm(m_before_project_release ? std::function<bool(bool)>{} : check)) == wxID_CANCEL) ||
        (skip_confirm && m_before_project_release && !m_before_project_release()))
        return wxID_CANCEL;

    // Rebase note: keep these two upstream resets after the release guard.
    // They used to run at function entry, which mutated the old project even
    // when a failed durable save canceled replacement.
    model().calib_pa_pattern.reset(nullptr);
    model().plates_custom_gcodes.clear();

    ProjectStateTransaction project_change = project_state_transaction();

    m_only_gcode = false;
    m_exported_file = false;
    m_loading_project = false;
    get_notification_manager()->clear_all();

    if (!silent)
        wxGetApp().mainframe->select_tab(TAB_ID_PREPARE);

    //get_partplate_list().reinit();
    //get_partplate_list().update_slice_context_to_current_plate(p->background_process);
    //p->preview->update_gcode_result(p->partplate_list.get_current_slice_result());
    if (!silent) {
        Slic3r::LifecycleEventContext ctx;
        ctx.code = Slic3r::LifecycleEvtCode::Ok;
        Slic3r::fire_lifecycle_event(Slic3r::LifecycleEvent::NewProject, ctx);
    }
    {
        // Same rationale as in Plater::priv::reset(): the whole reset + preset-reload +
        // baseline-reset sequence below settles into its final dirty state only once it
        // completes, so hold notifications until then to avoid firing on transient flips.
        ProjectDirtyStateManager::NotificationSuppressor dirty_notify_suppressor(p->dirty_state);

        reset(transfer_preset_changes, reload_presets);
        reset_project_dirty_after_save();
        reset_project_dirty_initial_presets();
        wxGetApp().update_saved_preset_from_current_preset();
        update_project_dirty_from_presets();

        //reset project
        p->project.reset();
        //set project name
        if (project_name.empty())
            p->set_project_name(_L("Untitled"));
        else
            p->set_project_name(project_name);

        Plater::TakeSnapshot snapshot(this, "New Project", UndoRedo::SnapshotType::ProjectSeparator);
    }

    Model m;
    model().load_from(m); // new id avoid same path name

    //select first plate
    get_partplate_list().select_plate(0);
    SimpleEvent event(EVT_GLCANVAS_PLATE_SELECT);
    p->on_plate_selected(event);

    p->load_auxiliary_files();
    wxGetApp().app_config->update_last_backup_dir(model().get_backup_path());

    // BBS set default view and zoom
    p->select_view_3D("3D");
    p->select_view("topfront");
    p->camera.requires_zoom_to_bed = true;
    enable_sidebar(!m_only_gcode);

    up_to_date(true, false);
    up_to_date(true, true);
    // clear_all() above also removed the missing-plugin notices; show them again for the current presets.

