std::optional<std::vector<ProjectAutosave::ManagedProject>> ProjectAutosave::projects()
{
    settle(true);
    // Home can be opened before the first project switch. Render the current
    // project once here; the preview is independent of the frequent backups.
    ensure_current_preview();
    const auto folders = project_folders(m_root);
    if (!folders)
        return std::nullopt;
    std::vector<ManagedProject> result;
    for (const auto& folder : *folders) {
        try {
            // Inside the try: a project folder that cannot be read is skipped
            // like any other unavailable project, not the whole list.
            if (!std::filesystem::is_directory(folder) || !std::filesystem::exists(folder / "HEAD"))
                continue;
            if (!authored_head(folder))
                continue;
            const std::string id = folder.filename().string();
            const auto add = [&result, &folder, &id](const ProjectVersionStore::Version& version,
                                                     const Agent::ProjectStateDocument& document, bool readable) {
                const auto source = std::filesystem::u8path(version.source_path);
                const std::string name = !version.project_name.empty() ? version.project_name : source.stem().u8string();
                ManagedProject project{id, name, version.created_at, version.source_path, folder.u8string()};
                if (readable)
                    project.gcodes = document.gcode_records();
                try {
                    project.thumbnail_url = saved_preview(folder, version.id);
                    if (project.thumbnail_url.empty()) {
                        // A project whose latest version was never rendered
                        // here has no preview sidecar for it. Orca's original
                        // 3MF thumbnail keeps its Home card useful until the
                        // project is next opened and rendered locally.
                        project.thumbnail_url = source_preview(version.source_path);
                        if (!project.thumbnail_url.empty())
                            write_preview(folder, version.id, project.thumbnail_url);
                    }
                } catch (const std::exception& error) {
                    // A damaged preview must not hide an otherwise healthy
                    // local project from Home.
                    BOOST_LOG_TRIVIAL(warning) << "Local project preview unavailable: " << error.what();
                }
                result.push_back(std::move(project));
            };
            // The open project's document is the one in memory, which can be
            // ahead of the file by the last few seconds of edits.
bool ProjectAutosave::save_now()
{
    try {
        adopt_project();
        settle(true); // A failed older write can be retried from the live model.
        m_store->ensure_durable_head();
        observe_document_change();
        if (blank()) {
            m_error.clear();
            m_state = State::Saved;
            return true;
        }
        if (!m_store->head_id().empty() && !m_last_capture_input.empty() &&
            observed_input() == m_last_capture_input) {
            if (m_persistence.document().doc_revision() != m_committed_semantic_revision)
                return persist_document(true);
            m_error.clear();
            m_state = State::Saved;
            return true;
        }
        GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
        if (canvas == nullptr || !canvas->is_initialized()) {
            fail("The project canvas is not ready for a durable save");
            return false;
        }
        if (canvas->get_gizmos_manager().is_in_editing_mode(true)) {
            fail("Finish the current tool edit before replacing the project");
            return false;
        }
        return capture(true);
    } catch (const std::exception& error) {
        fail(error.what());
        return false;
    }
}

std::string ProjectAutosave::current_version() const
{
    return m_committed_head;
}

std::vector<ProjectVersionStore::Version> ProjectAutosave::history()
{
    if (m_worker.valid())
        settle(true);
    return m_store ? m_store->history() : std::vector<ProjectVersionStore::Version>{};
}

std::optional<std::string> ProjectAutosave::pin_current()
{
    if (!save_now())
        return std::nullopt;
    const std::string id = m_store->head_id();
    if (id.empty())
        return id;
    try {
        m_store->pin(id);
    } catch (const std::exception& error) {
        // Pinning writes into the project folder like any save, so a folder
        // that cannot be written is a failed save, reported and retried.
        fail(error.what());
        return std::nullopt;
    }
    return id;
}

void ProjectAutosave::record_agent_operation(const std::string& action_id, const std::string& tool,
                                             const std::string& outcome, const std::string& before, bool save)
{
    const bool saved = save && save_now();
    if (!before.empty())
        m_store->record_operation(action_id, tool, outcome, before, saved ? m_committed_head : std::string());
    if (save && !saved)
        throw std::runtime_error(m_error);
}

bool ProjectAutosave::restore(const std::string& version_id)
{
    return restore_impl(version_id, {});
}

bool ProjectAutosave::restore_chat(const std::string& version_id, const std::string& conversation_id)
{
    return restore_impl(version_id, conversation_id);
}

bool ProjectAutosave::restore_impl(const std::string& version_id, const std::string& conversation_id)
{
    const bool chat = !conversation_id.empty();
    std::string before_id;
    std::string before_state;
    std::optional<ProjectVersionStore::Materialization> materialized;
    bool replacement_started = false;
    bool marker_written = false;
    try {
        if (!save_now())
            return false;
        if (version_id == m_committed_head && !chat)
            return true;
        before_id = m_committed_head;
